// ─── File: CloudFrontDemo.java ───
package com.bank.cf;

import java.time.*;
import java.util.logging.*;

public class CloudFrontDemo {
    private static final Logger log = Logger.getLogger("CF");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Origin s3 = new Origin("s3-assets");
        s3.put("/static/logo.png", "LOGO_BYTES");
        Origin albPrimary = new Origin("alb-api");
        Origin albDr = new Origin("alb-api-dr");
        albDr.put("/api/balance", "BALANCE_FROM_DR");

        CloudFrontSimulator cf = new CloudFrontSimulator();
        cf.addBehavior(new CacheBehavior("/static/*", s3, 86_400)); // cache 1 day
        cf.addBehavior(new CacheBehavior("/api/*",
            new OriginGroup("api", albPrimary, albDr), 0));          // no cache, failover

        // Static asset: MISS then HIT
        log.info(() -> "static1 " + cf.get("/static/logo.png", null));
        log.info(() -> "static2 " + cf.get("/static/logo.png", null));

        // API call: accelerated, uncached, served from primary
        albPrimary.put("/api/balance", "BALANCE_FROM_PRIMARY");
        log.info(() -> "api " + cf.get("/api/balance", null));

        // Primary API fails → origin group fails over to DR
        albPrimary.setDown(true);
        log.info(() -> "api failover " + cf.get("/api/balance", null));

        // Premium report: signed URL required
        String path = "/reports/premium/portfolio-SAV2001.pdf";
        s3.put(path, "PREMIUM_REPORT_BYTES");
        cf.addBehavior(new CacheBehavior("/reports/*", s3, 300));
        String token = cf.issueSignedToken(path, Instant.now().plus(Duration.ofMinutes(10)));
        log.info(() -> "premium with valid token: " + cf.getPremium(path, token));
        log.info(() -> "premium with bad token: " + cf.getPremium(path, "forged"));

        // Invalidate the logo path
        cf.invalidate("/static/logo.png");
        log.info(() -> "static after invalidation " + cf.get("/static/logo.png", null));
    }
}

