// ─── File: Origin.java ───
package com.bank.cf;

import java.util.*;
import java.util.logging.*;

public class Origin {
    private static final Logger log = Logger.getLogger("CF");
    private final String name;
    private final Map<String,String> store = new HashMap<>();
    private boolean down = false;

    public Origin(String name) { this.name = name; }
    public String name() { return name; }
    public void put(String path, String body) { store.put(path, body); }
    public void setDown(boolean d) { this.down = d; }
    public boolean isDown() { return down; }
    public String fetch(String path) {
        if (down) throw new RuntimeException(name + " is DOWN");
        log.info(() -> "ORIGIN " + name + " fetch " + path);
        return store.get(path);
    }
}
