package com.bank.cf;

import java.util.logging.*;

// Primary with automatic failover to secondary.
public class OriginGroup extends Origin {
    private static final Logger log = Logger.getLogger("CF");
    private final Origin primary;
    private final Origin secondary;

    public OriginGroup(String name, Origin primary, Origin secondary) {
        super(name);
        this.primary = primary; this.secondary = secondary;
    }
    @Override public String fetch(String path) {
        try { return primary.fetch(path); }
        catch (RuntimeException e) {
            log.warning(() -> "primary failed, failing over to " + secondary.name());
            return secondary.fetch(path);
        }
    }
}
