// ─── File: CloudFrontSimulator.java ───
package com.bank.cf;

import java.time.Instant;
import java.util.*;
import java.util.logging.*;

public class CloudFrontSimulator {
    private static final Logger log = Logger.getLogger("CF");
    private final List<CacheBehavior> behaviors = new ArrayList<>();
    private final Map<String,String> edgeCache = new HashMap<>();
    private final Map<String,Instant> signedTokens = new HashMap<>();

    public void addBehavior(CacheBehavior b) { behaviors.add(b); }

    private CacheBehavior behaviorFor(String path) {
        return behaviors.stream().filter(b -> b.matches(path)).findFirst()
            .orElseThrow(() -> new IllegalStateException("no behavior for " + path));
    }

    public String get(String path, String ignored) {
        CacheBehavior b = behaviorFor(path);
        if (b.ttlSeconds() > 0 && edgeCache.containsKey(path)) {
            log.info(() -> "EDGE HIT " + path);
            return edgeCache.get(path);
        }
        String body = b.origin().fetch(path);               // miss or uncacheable
        if (b.ttlSeconds() > 0) edgeCache.put(path, body);    // cache only if cacheable
        else log.fine(() -> "accelerated (uncached) " + path);
        return body;
    }

    // signed URL: issue a time-limited token; verify on premium fetch
    public String issueSignedToken(String path, Instant expiry) {
        String token = Integer.toHexString((path + expiry).hashCode());
        signedTokens.put(token, expiry);
        return token;
    }
    public String getPremium(String path, String token) {
        Instant exp = signedTokens.get(token);
        if (exp == null || Instant.now().isAfter(exp)) {
            log.warning(() -> "ACCESS DENIED (invalid/expired token) " + path);
            return "403 Forbidden";
        }
        return behaviorFor(path).origin().fetch(path);
    }

    public void invalidate(String path) {
        edgeCache.remove(path);
        log.warning(() -> "invalidation issued for " + path);
    }
}
